#!/bin/zsh
# Reproduce every C++ experiment of the paper, stage by stage. Run from the repository root after building the solver
# (see README.md). Each stage appends to CSVs under experiments/solver/ and writes a log; the paper's Table 2 is then
# regenerated by solver/build/make_tables. Walls are the ones used in the paper (7,200 s at 25-40 sites, 14,400 s at
# 50); the full run takes several days on an 8-core laptop, so stages can be run one at a time:
#
#   experiments/scripts/reproduce.sh instances      regenerate the table instances from their seeds and check them
#   experiments/scripts/reproduce.sh decomposed     Table 2 decomposed columns, seeds 1-5      (~1 h)
#   experiments/scripts/reproduce.sh mccormick      Table 2 McCormick columns, static + node-local (~3-4 days)
#   experiments/scripts/reproduce.sh mpi            Table 5, 1+7 ranks                          (~1 h)
#   experiments/scripts/reproduce.sh sensitivity    Table 3, decomposed + node-local McCormick  (~4 h)
#   experiments/scripts/reproduce.sh sparse         Table 6, 100/200/500 sites                  (~3 h incl. the m=100 run)
#   experiments/scripts/reproduce.sh unlinked       Table 1 unlinked column (root only, seeds 1-3)   (~10 min)
#   experiments/scripts/reproduce.sh mip            "McCormick inside a full MIP solver" paragraph  (~40 min)
#   experiments/scripts/reproduce.sh bpos0          b_s = 0 variant (referee 4): roots + trees        (~3 h)
#   experiments/scripts/reproduce.sh seedc2l        node-local McCormick seeded with the linked pool  (~2 h)
#   experiments/scripts/reproduce.sh msens          sensitivity in m, 30 sites, m = 15..200           (~2 h)
#   experiments/scripts/reproduce.sh tables         regenerate Table 2 and compile the paper
#   experiments/scripts/reproduce.sh all
#
# Use `caffeinate -i -s experiments/scripts/reproduce.sh all` on macOS so the machine does not sleep.
set -u
ROOT=$(cd "$(dirname "$0")/../.." && pwd)
SOLVER=$ROOT/solver; OUT=$ROOT/experiments/solver
ENDOG=$SOLVER/build/endog; MPIRUN=$SOLVER/third_party/openmpi/bin/mpirun; ENDOG_MPI=$SOLVER/build/endog_mpi
W=${WORKERS:-8}                       # threads for the recourse LPs (one per core)
cd "$SOLVER" || exit 1
mkdir -p "$OUT"
last() { grep -v "^\s*\[lp\]" | tail -1; }

stage_instances() {
  # The table instances are make_instance(n, 15, 20, seed) with the default PCG64 stream; the committed
  # files are regenerated into a temporary directory and compared, so a changed generator is noticed.
  T=$(mktemp -d)
  for n in 25 30 35 40 50 100; do for s in 1 2 3 4 5; do
    [ -f instances/n${n}_s${s}.txt ] || continue
    $ENDOG --n $n --seed $s --gen-only --save-inst $T/g.txt > /dev/null 2>&1
    if cmp -s <(tr -s ' \n' '\n\n' < instances/n${n}_s${s}.txt | awk '{printf "%.9g\n", $1}') <(tr -s ' \n' '\n\n' < $T/g.txt | awk '{printf "%.9g\n", $1}'); then echo "n${n}_s${s} ok"; else echo "n${n}_s${s} DIFFERS"; fi
  done; done
}

stage_decomposed() {
  LOG=$OUT/decomposed.log; : > $LOG
  for n in 25 30 35 40 50; do for s in 1 2 3 4 5; do
    wall=$([ $n -eq 50 ] && echo 14400 || echo 7200)
    echo "=== dec n$n s$s wall $wall" >> $LOG
    $ENDOG --master dec --inst instances/n${n}_s${s}.txt --workers $W --wall $wall --out $OUT/decomposed.csv 2>&1 | last >> $LOG
  done; done
  echo DONE >> $LOG
}

stage_mccormick() {
  LOG=$OUT/mccormick.log; : > $LOG
  run() { echo "=== $1 n$2 s$3 wall $4" >> $LOG; $ENDOG --master $1 --inst instances/n$2_s$3.txt --workers $W --wall $4 --out $OUT/mccormick.csv 2>&1 | last >> $LOG; }
  for n in 25 30 35 40; do for s in 1 2 3 4 5; do run mcb-dyn $n $s 7200; done; done   # node-local, seeds 1-5
  for s in 1 2 3 4 5; do run mcb-dyn 50 $s 14400; done
  for n in 25 30 35 40; do for s in 1 2 3; do run mcb $n $s 7200; done; done           # static, seeds 1-3
  for s in 1 2 3; do run mcb 50 $s 14400; done
  echo DONE >> $LOG
}

stage_mpi() {
  LOG=$OUT/mpi.log; : > $LOG
  for n in 40 50; do for s in 1 2 3; do
    echo "=== n${n}_s${s} single rank, $W threads" >> $LOG
    $ENDOG --inst instances/n${n}_s${s}.txt --workers $W --out $OUT/mpi_single.csv 2>&1 | last >> $LOG
    echo "=== n${n}_s${s} mpi 1+7, root once on rank 0, idle ranks yield" >> $LOG
    $MPIRUN --mca mpi_yield_when_idle 1 -np 8 $ENDOG_MPI --inst instances/n${n}_s${s}.txt --workers 1 --root-workers $W --out $OUT/mpi_1p7.csv 2>&1 | last >> $LOG
  done; done
  echo DONE >> $LOG
}

stage_sensitivity() {
  # Generated by the C++ generator (cgen_*): S = 50 and 100 strong, and S = 20 weak, n = 30, seeds 1-3.
  LOG=$OUT/sensitivity_rerun.log; : > $LOG
  gen() { [ -f instances/$1 ] || $ENDOG --n 30 --m 15 --S $2 --seed $3 --endo $4 --rng mt --gen-only --save-inst instances/$1 > /dev/null 2>&1; }
  for s in 1 2 3; do gen cgen_n30_S50_s$s.txt 50 $s strong; gen cgen_n30_S100_s$s.txt 100 $s strong; gen cgen_n30_weak_s$s.txt 20 $s weak; done
  for f in cgen_n30_S50_s{1,2,3}.txt cgen_n30_S100_s{1,2,3}.txt cgen_n30_weak_s{1,2,3}.txt; do
    echo "=== dec $f" >> $LOG;     $ENDOG --master dec     --inst instances/$f --workers $W --wall 3600 --out $OUT/sensitivity_dec.csv 2>&1 | last >> $LOG
    echo "=== mcb-dyn $f" >> $LOG; $ENDOG --master mcb-dyn --inst instances/$f --workers $W --wall 3600 --out $OUT/sensitivity_mcb.csv 2>&1 | last >> $LOG
  done
  echo DONE >> $LOG
}

stage_sparse() {
  LOG=$OUT/sparse_rerun.log; : > $LOG
  gen() { [ -f instances/$1 ] || $ENDOG --n $2 --m $3 --S 20 --seed $4 --density $5 --rng mt --gen-only --save-inst instances/$1 > /dev/null 2>&1; }
  for s in 1 2 3; do gen cgen_n100_den01_s$s.txt 100 15 $s 0.1; gen cgen_n200_den005_s$s.txt 200 15 $s 0.05; gen cgen_n500_den002_s$s.txt 500 15 $s 0.02; done
  gen cgen_n500_m100_den002_s1.txt 500 100 1 0.02
  for f in cgen_n100_den01_s{1,2,3}.txt cgen_n200_den005_s{1,2,3}.txt cgen_n500_den002_s{1,2,3}.txt cgen_n500_m100_den002_s1.txt; do
    echo "=== dec --sparse $f" >> $LOG
    $ENDOG --master dec --sparse --inst instances/$f --workers $W --wall 7200 --out $OUT/sparse_rerun.csv 2>&1 | last >> $LOG
  done
  echo DONE >> $LOG
}

stage_unlinked() {
  LOG=$OUT/unlinked_rerun.log; : > $LOG
  for n in 25 30 35 40 50; do for s in 1 2 3; do
    echo "=== unlinked root n$n s$s" >> $LOG
    $ENDOG --master dec --unlinked --root-only --inst instances/n${n}_s${s}.txt --workers $W --out $OUT/unlinked_rerun.csv 2>&1 | last >> $LOG
  done; done
  echo DONE >> $LOG
}

stage_mip() {
  LOG=$OUT/mip_rerun.log; : > $LOG
  for n in 30 40; do for s in 1 2 3; do
    echo "=== mcb-mip n$n s$s wall 7200 mip-time 1800" >> $LOG
    $ENDOG --master mcb-mip --inst instances/n${n}_s${s}.txt --workers $W --wall 7200 --mip-time 1800 --out $OUT/mip_rerun.csv 2>&1 | last >> $LOG
  done; done
  echo DONE >> $LOG
}

stage_bpos0() {
  LOG=$OUT/bpos0_rerun.log; : > $LOG
  for n in 25 30 35 40; do for s in 1 2 3; do
    f=instances/cgen_n${n}_bpos0_s$s.txt
    [ -f $f ] || $ENDOG --n $n --seed $s --bpos0 --rng mt --gen-only --save-inst $f > /dev/null 2>&1
    echo "=== bpos0 n$n s$s dec" >> $LOG;           $ENDOG --master dec --inst $f --workers $W --wall 3600 --out $OUT/bpos0_rerun.csv 2>&1 | last >> $LOG
    echo "=== bpos0 n$n s$s unlinked root" >> $LOG; $ENDOG --master dec --unlinked --root-only --inst $f --workers $W --out $OUT/bpos0_rerun.csv 2>&1 | last >> $LOG
    echo "=== bpos0 n$n s$s mcb-dyn root" >> $LOG;  $ENDOG --master mcb-dyn --root-only --inst $f --workers $W --out $OUT/bpos0_rerun.csv 2>&1 | last >> $LOG
  done; done
  for n in 25 30; do for s in 1 2 3; do
    echo "=== bpos0 n$n s$s mcb-dyn tree" >> $LOG
    $ENDOG --master mcb-dyn --inst instances/cgen_n${n}_bpos0_s$s.txt --workers $W --wall 3600 --out $OUT/bpos0_rerun.csv 2>&1 | last >> $LOG
  done; done
  echo DONE >> $LOG
}

stage_seedc2l() {
  LOG=$OUT/seedc2l_rerun.log; : > $LOG
  for n in 25 30 35; do for s in 1 2 3; do
    echo "=== seed-c2l mcb-dyn n$n s$s" >> $LOG
    $ENDOG --master mcb-dyn --seed-c2l --inst instances/n${n}_s${s}.txt --workers $W --wall 3600 --out $OUT/seedc2l_rerun.csv 2>&1 | last >> $LOG
  done; done
  echo DONE >> $LOG
}

stage_msens() {
  LOG=$OUT/msens_rerun.log; : > $LOG
  for m in 15 50 100 200; do for s in 1 2 3; do
    f=instances/cgen_n30_m${m}_s$s.txt
    [ -f $f ] || $ENDOG --n 30 --m $m --seed $s --rng mt --gen-only --save-inst $f > /dev/null 2>&1
    echo "=== msens m$m s$s dec" >> $LOG
    $ENDOG --master dec --inst $f --workers $W --wall 3600 --out $OUT/msens_rerun.csv 2>&1 | last >> $LOG
  done; done
  echo DONE >> $LOG
}

stage_tables() {
  cd "$ROOT" && $SOLVER/build/make_tables "$ROOT" > /dev/null && (cd paper && tectonic main.tex) && echo "paper/main.pdf rebuilt"
}

case "${1:-all}" in
  instances) stage_instances ;;
  decomposed) stage_decomposed ;;
  mccormick) stage_mccormick ;;
  mpi) stage_mpi ;;
  sensitivity) stage_sensitivity ;;
  sparse) stage_sparse ;;
  unlinked) stage_unlinked ;;
  mip) stage_mip ;;
  bpos0) stage_bpos0 ;;
  seedc2l) stage_seedc2l ;;
  msens) stage_msens ;;
  tables) stage_tables ;;
  all) stage_instances; stage_decomposed; stage_mccormick; stage_mpi; stage_sensitivity; stage_sparse; stage_unlinked; stage_mip; stage_bpos0; stage_seedc2l; stage_msens; stage_tables ;;
  *) echo "unknown stage $1"; exit 2 ;;
esac
